import sys
from collections import deque

data = sys.stdin.read().split()
n = int(data[0])
A = tuple(int(x) for x in data[1:1 + n])
B = tuple(int(x) for x in data[1 + n:1 + 2 * n])

if n <= 7:
    dist = {B: 0}
    q = deque([B])
    while q:
        cur = q.popleft()
        if cur == A:
            break
        for i in range(n):
            rest = cur[:i] + cur[i + 1:]
            for nxt in ((cur[i],) + rest, rest + (cur[i],)):
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    q.append(nxt)
    print(dist[A])
else:
    # keep a block A[l..r] untouched: it must appear in B as a subsequence; everything else is moved once
    def is_subseq(seg):
        it = iter(B)
        return all(x in it for x in seg)
    best = 0
    for l in range(n):
        for r in range(l, n):
            if r - l + 1 > best and is_subseq(A[l:r + 1]):
                best = r - l + 1
    print(n - best)

